import type { ArgTypes } from '@storybook/react-webpack5';
import * as React from 'react';
import type { JSXElement } from '@fluentui/react-components';
import { Avatar } from '@fluentui/react-components';
import type { AvatarProps } from '@fluentui/react-components';

export const Default = (props: Partial<AvatarProps>): JSXElement => <Avatar aria-label="Guest" {...props} />;

const argTypes: ArgTypes = {
  initials: {
    control: {
      type: 'text',
    },
  },
  badge: {
    control: {
      type: 'inline-radio',
      options: [{ status: 'away' }, { status: 'busy' }],
    },
  },
  size: {
    control: {
      type: 'select',
      options: [16, 20, 24, 28, 32, 36, 40, 48, 56, 64, 72, 96, 120, 128],
    },
  },
  name: {
    control: {
      type: 'text',
    },
  },
};

Default.argTypes = argTypes;

import * as React from 'react';
import type { JSXElement } from '@fluentui/react-components';
import { Avatar } from '@fluentui/react-components';

export const Name = (): JSXElement => <Avatar name="Ashley McCarthy" />;

Name.storyName = 'Name';
Name.parameters = {
  docs: {
    description: {
      story: 'The name is used to determine the initials displayed by the Avatar. It is also read by screen readers.',
    },
  },
};

import * as React from 'react';
import type { JSXElement } from '@fluentui/react-components';
import { Avatar } from '@fluentui/react-components';

export const Image = (): JSXElement => (
  <Avatar
    name="Katri Athokas"
    image={{ src: 'https://fabricweb.azureedge.net/fabric-website/assets/images/avatar/KatriAthokas.jpg' }}
  />
);

Image.parameters = {
  docs: {
    description: {
      story:
        'An avatar can display an image.<br/>' +
        'It is recommended to also include a name in addition to the image: the initials from the name are ' +
        'displayed while the image is loading, and the name makes the Avatar accessible to screen readers.',
    },
  },
};

